/* Update of the class 0xB8 shot (spawned by FUN_L04_002aee30): moves along its direction, plays its sound once it starts moving away from the hero within 3 units, dies off the arena, and on a hit (probing for its owner's targets until the timer runs out) bursts into five sparks and is removed.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/002aee30.c, FUN_L04_002af058. */
void update_class_b8_projectile(struct Moby *m)
{
    Vec4 old;
    CollisionProbe pr;
    Vec4 push;
    Vec4 r;
    ShotVars *v = (ShotVars *)m->pvars;
    CollisionProbe *probe;
    f32 range;
    f32 d;
    s32 i;

    range = 64.0f;
    if (v->owner->oclass == 0xFF)
        range = 128.0f;
    if ((*(s32 *)&g_current_level_index) == 12)
        range = 100.0f;
    d = FastVecDist(&m->pos, &g_hero.motion.pos);
    qcopy(&old, &m->pos);
    FastVecAdd(&m->pos, &m->pos, &v->dir);
    if (v->unk28 == 0 && v->unk24 != 0 && v->hero_dist < d && d < 3.0f) {
        Moby_PlaySound(0, 0, m);
        v->unk28 = 1;
    }
    if (d < v->hero_dist)
        v->unk24 = 1;
    v->hero_dist = d;
    if (m->pos.x < 0.0f || m->pos.y < 0.0f || m->pos.z < 0.0f
        || range < vec_distance_xy(&m->pos, eudora_camera_pos)) {
        DeleteMoby(m);
        return;
    }

    probe = 0;
    if (m->command == 0) {
        pr.self = m;
        if (v->owner->oclass == 0xFF || v->owner->oclass == 0x4B1) {
            pr.mask = 0x50001;
            pr.radius = 3.0f;
        } else {
            pr.mask = 0x10001;
            pr.radius = 1.0f;
        }
        pr.unk20 = 1;
        qcopy(&pr.dir, &v->dir);
        vec_set_length_xy(&pr.dir, &pr.dir, 1.0f);
        probe = &pr;
        pr.dir.v.z = 1.0f;
        pr.dir.v.w = 5627.9248f;
        pr.unk19 = pr.unk18 = 1;
        pr.oclass = m->oclass;
    }
    if (FastDecTimer(&v->time) && m->command == 0) {
        m->command = 1;
        v->time = v->time_max / 4;
    } else if (v->time <= 0 && m->command != 0) {
        DeleteMoby(m);
        return;
    }
    if (coll_line(&old, &m->pos, 0, v->owner, probe) == 0)
        return;

    qcopy(&m->pos, &eudora_coll_hit_point);
    if (m->command == 0) {
        for (i = 0; i < 5; i++) {
            r.q = 0;
            r.f[0] = random_float_between(-1.0f, 1.0f);
            r.f[1] = random_float_between(-1.0f, 1.0f);
            r.f[2] = random_float_between(-1.0f, 1.0f);
            push.q = r.q;
            vec_reflect(&r, v, eudora_coll_hit_normal);
            vec_scale_to_length(&push, &push, FastVecLength(&r) * 0.5f);
            FastVecAdd(&push, &r, &push);
            vec_scale_to_length(&push, &push, random_float_between(g_frame_time * 3.0f, g_frame_time * 6.0f));
            PartType27Spawn(&m->pos, &push, 0x7F2F4F6F,
                             rand_range(scale_ticks(10), scale_ticks(15)), 30000.0f);
        }
    }
    DeleteMoby(m);
}
